(2323988, 320842, 16241, '<td valign="top">nice!</td>', 'nice!', '2006-04-19 02:03:17.000000', NULL, 1),
(2323991, 322142, 41802, '<td valign="top">Excellent piece, very moody.</td>', 'Excellent piece, very moody.', '2006-04-19 02:03:59.000000', NULL, 1),
(2323996, 321981, 41802, '<td valign="top">Wow interesting capture. That must be some old wood to be able to carve that deep.</td>', 'Wow interesting capture. That must be some old wood to be able to carve that deep.', '2006-04-19 02:04:40.000000', NULL, 1),
(2324002, 320666, 6804, '<td valign="top">A great pose! The burnt sky is just a little distracting to me, but it does help to bring out the subject. I do like the long grass in the way.</td>', 'A great pose! The burnt sky is just a little distracting to me, but it does help to bring out the subject. I do like the long grass in the way.', '2006-04-19 02:05:24.000000', NULL, 1),
(2324005, 320901, 41802, '<td valign="top">Very interesting light house, nice sepia shot.</td>', 'Very interesting light house, nice sepia shot.', '2006-04-19 02:06:39.000000', NULL, 1),
(2324013, 321301, 16241, '<td valign="top">similar style to blue ribbon, hmmmmmmmmmmm  cute</td>', 'similar style to blue ribbon, hmmmmmmmmmmm  cute', '2006-04-19 02:08:41.000000', NULL, 1),
(2324016, 322882, 41802, '<td valign="top">Prefect for the DP environment.</td>', 'Prefect for the DP environment.', '2006-04-19 02:10:36.000000', NULL, 1),
(2324020, 320541, 41802, '<td valign="top">Wow very old and interesting. Nice soft feel.</td>', 'Wow very old and interesting. Nice soft feel.', '2006-04-19 02:11:51.000000', NULL, 1),
