(2325307, 321196, 36831, '<td valign="top">Great contrast and DOF</td>', 'Great contrast and DOF', '2006-04-19 10:22:47.000000', NULL, 1),
(2325310, 322288, 51638, '<td valign="top">Well done. Nice exposure.</td>', 'Well done. Nice exposure.', '2006-04-19 10:23:03.000000', NULL, 1),
