(2326385, 322509, 52549, '<td valign="top">This is a beautiful image. B/W suits it perfectly.</td>', 'This is a beautiful image. B/W suits it perfectly.', '2006-04-19 16:18:49.000000', NULL, 1),
(2326387, 320699, 15711, '<td valign="top">Lovely worn out pier.  The city lights in the background brings home how progress has left this old structure behing.  The sky is lovely.</td>', 'Lovely worn out pier.  The city lights in the background brings home how progress has left this old structure behing.  The sky is lovely.', '2006-04-19 16:18:56.000000', NULL, 1),
(2326406, 320848, 52549, '<td valign="top">Very cleverly done and well photographed.</td>', 'Very cleverly done and well photographed.', '2006-04-19 16:22:10.000000', NULL, 1),
(2326428, 322810, 52549, '<td valign="top">Very subtle. Thought a first glance that it was b/w, then I saw the colour. Very well photographed.</td>', 'Very subtle. Thought a first glance that it was b/w, then I saw the colour. Very well photographed.', '2006-04-19 16:25:32.000000', NULL, 1),
(2326429, 321719, 1009, '<td valign="top">Its sad when this happens to parrots, hopefully someone has taken it to the vet before it dies.</td>', 'Its sad when this happens to parrots, hopefully someone has taken it to the vet before it dies.', '2006-04-19 16:25:45.000000', NULL, 1),
