(2326440, 322809, 52549, '<td valign="top">I like it, it''s well photographed and has a sentimental touch.</td>', 'I like it, it''s well photographed and has a sentimental touch.', '2006-04-19 16:27:33.000000', NULL, 1),
(2326446, 323028, 1009, '<td valign="top">A little to light for me, almost looks over processed.</td>', 'A little to light for me, almost looks over processed.', '2006-04-19 16:29:00.000000', NULL, 1),
(2326448, 322976, 1009, '<td valign="top">Nice shot, good contrast and colors. Wish it was a little more filling the frame though...</td>', 'Nice shot, good contrast and colors. Wish it was a little more filling the frame though...', '2006-04-19 16:29:23.000000', NULL, 1),
(2326453, 322314, 1009, '<td valign="top">Quite a few camera shots in this challenge, glad I didn''t enter mine! Good job, like the desaturation and crisp sharpness.</td>', 'Quite a few camera shots in this challenge, glad I didn''t enter mine! Good job, like the desaturation and crisp sharpness.', '2006-04-19 16:30:33.000000', NULL, 1),
