(2326757, 322195, 43774, '<td valign="top">I would like to see more of the boat and not at such an extreme angle.</td>', 'I would like to see more of the boat and not at such an extreme angle.', '2006-04-19 17:32:46.000000', NULL, 1),
(2326758, 320124, 43774, '<td valign="top">Image looks to be slightly out of focus</td>', 'Image looks to be slightly out of focus', '2006-04-19 17:33:05.000000', NULL, 1),
(2326759, 322390, 15810, '<td valign="top">Well done, you''ve managed to capture the essence of the evening light in your picture. The keys have a nice texture and the colours are well subdued. Nice work.</td>', 'Well done, you''ve managed to capture the essence of the evening light in your picture. The keys have a nice texture and the colours are well subdued. Nice work.', '2006-04-19 17:33:15.000000', NULL, 1),
