(2331169, 322823, 51802, '<td valign="top">That bone is practically new!</td>', 'That bone is practically new!', '2006-04-20 23:18:37.000000', NULL, 1),
(2331178, 321401, 49202, '<td valign="top">burn marks showing...</td>', 'burn marks showing...', '2006-04-20 23:21:35.000000', NULL, 1),
