INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2331223, 321602, 51802, '<td valign="top">Interesting subject for Something Old.  There is also one in the Something New challenge.</td>', 'Interesting subject for Something Old.  There is also one in the Something New challenge.', '2006-04-20 23:33:12.000000', NULL, 1),
(2331226, 321597, 51802, '<td valign="top">I really don''t get this one.  She doesn''t look old or stressed.</td>', 'I really don''t get this one.  She doesn''t look old or stressed.', '2006-04-20 23:34:21.000000', NULL, 1),
(2331227, 322497, 49202, '<td valign="top">Had you shot this at sunrise- or sunset-time, bumped up the contrast, moved [or zoomed] in a bit closer, or cropped out the distracting white wood stuff and OOF foliage below, this would''ve gotten a ten from me.<br/>Yours was such a kickass subject and would''ve been a kickass photo, IMO.</td>', 'Had you shot this at sunrise- or sunset-time, bumped up the contrast, moved [or zoomed] in a bit closer, or cropped out the distracting white wood stuff and OOF foliage below, this would''ve gotten a ten from me.Yours was such a kickass subject and would''ve been a kickass photo, IMO.', '2006-04-20 23:34:28.000000', NULL, 1),
(2331232, 321496, 51802, '<td valign="top">Took me several seconds to figure out what this is.  I think it would be much more dramatic if the focus was on the speakers and not the screen.</td>', 'Took me several seconds to figure out what this is.  I think it would be much more dramatic if the focus was on the speakers and not the screen.', '2006-04-20 23:35:50.000000', NULL, 1),
(2331238, 322821, 49202, '<td valign="top">i have nothing about the subject, but i think the lighting and composition could''ve been better.</td>', 'i have nothing about the subject, but i think the lighting and composition could''ve been better.', '2006-04-20 23:36:49.000000', NULL, 1),
(2331239, 321418, 51802, '<td valign="top">The angle is off just enough so that I can''t tell if you did it on purpose or accident.  I think I would prefer it more if it were level.</td>', 'The angle is off just enough so that I can''t tell if you did it on purpose or accident.  I think I would prefer it more if it were level.', '2006-04-20 23:37:09.000000', NULL, 1),
(2331244, 320124, 51802, '<td valign="top">The flash is too harsh in this shot.</td>', 'The flash is too harsh in this shot.', '2006-04-20 23:39:00.000000', NULL, 1),
(2331249, 323006, 49202, '<td valign="top">um, it looks over-processed...</td>', 'um, it looks over-processed...', '2006-04-20 23:40:24.000000', NULL, 1),
(2331255, 320848, 51802, '<td valign="top">Great idea!  (I think the 4th from the left is in the wrong spot)  :-)</td>', 'Great idea!  (I think the 4th from the left is in the wrong spot)  :-)', '2006-04-20 23:41:41.000000', NULL, 1),
(2331259, 323205, 51802, '<td valign="top">You are so right about this!!!</td>', 'You are so right about this!!!', '2006-04-20 23:42:22.000000', NULL, 1),
